def smallest_multiple(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def sieve(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, limit+1, i):
                    is_prime[j] = False
        primes = [i for i, val in enumerate(is_prime) if val]
        return primes

    def prime_factors(n):
        factors = {}
        while n % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            n //= 2
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n //= i
            i += 2
        if n > 1:
            factors[n] = 1
        return factors

    def lcm(a, b):
        return a * b // gcd(a, b)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def compute_lcm_of_range(start, end):
        lcm_value = 1
        for i in range(start, end + 1):
            lcm_value = lcm(lcm_value, i)
        return lcm_value

    return compute_lcm_of_range(1, n)
```

