def find_closet(arr1, arr2, arr3, n1, n2, n3):
    # Initialize the closest triplet
    closest = (arr1[0], arr2[0], arr3[0])
    min_diff = float('inf')

    # Iterate through all possible combinations of elements from the three arrays
    for i in range(min(n1, 3)):
        for j in range(min(n2, 3)):
            for k in range(min(n3, 3)):
                current = (arr1[i], arr2[j], arr3[k])
                diff = sum(abs(a - b) for a, b in zip(current, closest))
                if diff < min_diff:
                    min_diff = diff
                    closest = current
    return closest
