def min_Swaps(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        raise ValueError("Strings must be of the same length")

    # Count the number of differing characters
    diff_count = sum(c1 != c2 for c1, c2 in zip(s1, s2))

    # If there are no differences, no swaps are needed
    if diff_count == 0:
        return 0

    # If there are an odd number of differences, it's impossible to convert
    if diff_count % 2 != 0:
        return -1

    # Count the number of positions where s1 has '0' and s2 has '1'
    # and vice versa (this is the number of swaps needed)
    swap_count = 0
    for c1, c2 in zip(s1, s2):
        if c1 == '0' and c2 == '1':
            swap_count += 1
        elif c1 == '1' and c2 == '0':
            swap_count += 1

    # Each swap fixes two differences, so divide by 2
    return swap_count // 2
```

