def lobb_num(n, m):
    class LobbNumber:
        def __init__(self, n, m):
            self.n = n
            self.m = m

        def compute(self):
            if self.m == 0:
                return 1
            if self.m == 1:
                return self.n
            if self.m > self.n:
                return 0
            return self.compute(self.n - 1, self.m - 1) + self.compute(self.n - 2, self.m - 1)

    return LobbNumber(n, m).compute()
