def rgb_to_hsv(r, g, b):
    r /= 255.0
    g /= 255.0
    b /= 255.0

    max_val = max(r, g, b)
    min_val = min(r, g, b)
    diff = max_val - min_val

    h = 0.0
    s = 0.0
    v = max_val

    if diff != 0:
        s = diff / max_val
        if max_val == r:
            h = (g - b) / diff
            if h < 0:
                h += 1
        elif max_val == g:
            h = (b - r) / diff
            if h < 0:
                h += 2
        elif max_val == b:
            h = (r - g) / diff
            if h < 0:
                h += 3
    else:
        h = 0.0
        s = 0.0

    h = h * 60.0
    if h < 0:
        h += 360.0

    return (h, s, v * 100.0)
