def rencontres_number(n, k):
    def factorial(x):
        if x == 0:
            return 1
        return x * factorial(x - 1)

    def derangement(n):
        if n == 0:
            return 1
        if n == 1:
            return 0
        return (n - 1) * (derangement(n - 1) + derangement(n - 2))

    if k > n:
        return 0

    # Using inclusion-exclusion principle to calculate the nth Rencontres number for k
    # The formula is: D(n, k) = sum_{i=0}^k (-1)^i * C(k, i) * (k - i)^n
    result = 0
    for i in range(k + 1):
        sign = (-1) ** i
        comb = factorial(k) // (factorial(i) * factorial(k - i))
        term = sign * comb * (k - i) ** n
        result += term

    return result
```

