def sum_of_odd_factors(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def prime_factors(n):
        factors = {}
        while n % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            n //= 2
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n //= i
            i += 2
        if n > 1:
            factors[n] = 1
        return factors

    factors = prime_factors(n)
    odd_factors = [p for p in factors if p % 2 != 0]
    if not odd_factors:
        return 0
    product = 1
    for p in odd_factors:
        product *= (p ** (factors[p] + 1)) - 1
    return product
```

