def largest_subset(nums, k):
    from collections import defaultdict

    def is_divisible(a, b):
        return a % b == 0 or b % a == 0

    class TrieNode:
        def __init__(self):
            self.children = defaultdict(TrieNode)

    def dfs(node, nums, k, count):
        if not nums:
            return count
        if not node:
            return 0
        max_count = 0
        for num in nums:
            if is_divisible(num, k):
                new_node = node.children[num]
                new_count = dfs(new_node, nums, k, count + 1)
                max_count = max(max_count, new_count)
        return max_count

    root = TrieNode()
    for num in nums:
        current = root
        for i in range(32):
            bit = (num >> i) & 1
            current = current.children[bit]
    return dfs(root, nums, k, 0)
```

