def get_median(arr1, arr2, n):
    # Merge the two sorted arrays using a two-pointer approach
    i = 0  # Pointer for arr1
    j = 0  # Pointer for arr2
    count = 0
    median = 0.0

    # Traverse both arrays until we reach the middle element
    while i < n and j < n:
        count += 1
        if i < n and (j == n or arr1[i] < arr2[j]):
            median = arr1[i]
            i += 1
        else:
            median = arr2[j]
            j += 1

    # If the total elements is even, take the average of the two middle elements
    if n % 2 == 0:
        # We need the second middle element
        if i < n and j < n:
            median += arr2[j] if arr1[i] < arr2[j] else arr1[i]
        else:
            median += arr1[i] if i < n else arr2[j]
        median /= 2
    else:
        # For odd number of elements, the median is the middle element
        if i < n and j < n:
            median = arr1[i] if arr1[i] < arr2[j] else arr2[j]
        else:
            median = arr1[i] if i < n else arr2[j]

    return median
```

