import heapq

def combine_lists(list1, list2):
    # Create a heap with the first elements of each list
    heap = []
    if list1:
        heapq.heappush(heap, (list1[0], 0, 1))
    if list2:
        heapq.heappush(heap, (list2[0], 0, 2))

    result = []
    while heap:
        val, i, lst = heapq.heappop(heap)
        result.append(val)
        if i + 1 < len(list1) and lst == 1:
            heapq.heappush(heap, (list1[i + 1], i + 1, 1))
        if i + 1 < len(list2) and lst == 2:
            heapq.heappush(heap, (list2[i + 1], i + 1, 2))
    return result
```

