def coin_change(coins, amount, target):
    class Memo:
        def __init__(self):
            self.cache = {}

        def get(self, key):
            return self.cache.get(key, -1)

        def set(self, key, value):
            self.cache[key] = value

    memo = Memo()

    def dp(i, remaining):
        if remaining == 0:
            return 1
        if i >= len(coins) or remaining < 0:
            return 0
        key = (i, remaining)
        if memo.get(key) != -1:
            return memo.get(key)

        # Use the current coin
        use = dp(i + 1, remaining - coins[i])
        # Skip the current coin
        skip = dp(i + 1, remaining)

        memo.set(key, use + skip)
        return use + skip

    return dp(0, target)
```

