def count_Fac(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def get_prime_factors(n):
        factors = {}
        if n % 2 == 0:
            count = 0
            while n % 2 == 0:
                n //= 2
                count += 1
            factors[2] = count
        i = 3
        while i * i <= n:
            while n % i == 0:
                if i not in factors:
                    factors[i] = 0
                factors[i] += 1
                n //= i
            i += 2
        if n > 1:
            if n not in factors:
                factors[n] = 1
            else:
                factors[n] += 1
        return factors

    prime_factors = get_prime_factors(n)
    return len(prime_factors)
```

