def bell_number(n):
    if n == 0:
        return 1
    # Initialize a 2D list to store Bell numbers
    bell = [[0] * (n + 1) for _ in range(n + 1)]

    # First column of Bell triangle is 1
    for i in range(n + 1):
        bell[i][0] = 1

    # Fill the Bell triangle
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            bell[i][j] = bell[i - 1][j - 1] + bell[i][j - 1]

    return bell[n][n]
```

