def check_expression(expr):
    class Stack:
        def __init__(self):
            self._items = []

        def push(self, item):
            self._items.append(item)

        def pop(self):
            if not self._items:
                return None
            return self._items.pop()

        def is_empty(self):
            return not self._items

    stack = Stack()
    open_brackets = '({['
    close_brackets = ')}]'

    for char in expr:
        if char in open_brackets:
            stack.push(char)
        elif char in close_brackets:
            if stack.is_empty():
                return False
            top = stack.pop()
            if close_brackets.index(char) != open_brackets.index(top):
                return False

    return stack.is_empty()
```

