def min_Swaps(s1: str, s2: str) -> int:
    # Check if the lengths of the strings are equal
    if len(s1) != len(s2):
        return -1  # or raise an error, but function returns int

    # Count the number of differing characters
    diff_count = 0
    for c1, c2 in zip(s1, s2):
        if c1 != c2:
            diff_count += 1

    # If there are no differences, no swaps are needed
    if diff_count == 0:
        return 0

    # If there are an odd number of differences, it's impossible to make them equal
    if diff_count % 2 != 0:
        return -1

    # The minimum number of swaps needed is half the number of differences
    return diff_count // 2
```

