def max_chain_length(pairs, n):
    # Sort the pairs based on the second element of the pair
    pairs.sort(key=lambda x: x.b)

    # Initialize the dp array
    dp = [1] * n

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if pairs[i].a > pairs[j].b:
                dp[i] = max(dp[i], dp[j] + 1)

    return dp[-1]
