FUNCTION NAME: GENERATEALUMINUMCOLOR

DESCRIPTION: THIS FUNCTION CREATES A RANDOM HEX COLOR CODE THAT SIMULATES THE APPEARANCE OF ALUMINUM METAL.

LOGIC: ALUMINUM HAS A SHINY, SILVER-SHADED APPEARANCE. HEX COLORS ARE 6 CHARACTER CODES MADE UP OF 0-9 AND A-F. TO SIMULATE ALUMINUM, WE USE A SHINY, LIGHT GRAY TO SILVER RANGE, WITH A SLIGHTLY GREY TONE.

IMPLEMENTATION:

FUNCTION GENERATEALUMINUMCOLOR() {
  // GENERATE RANDOM VALUES FOR RED, GREEN, BLUE
  let RED = Math.floor(Math.random() * 160) + 100;
  let GREEN = Math.floor(Math.random() * 160) + 100;
  let BLUE = Math.floor(Math.random() * 160) + 100;

  // CONVERT NUMBERS TO HEX STRING
  let REDHEX = RED.toString(16);
  let GREENHEX = GREEN.toString(16);
  let BLUEHEX = BLUE.toString(16);

  // PAD WITH LEADING ZERO IF NEEDED
  REDHEX = REDHEX.length === 1 ? '0' + REDHEX : REDHEX;
  GREENHEX = GREENHEX.length === 1 ? '0' + GREENHEX : GREENHEX;
  BLUEHEX = BLUEHEX.length === 1 ? '0' + BLUEHEX : BLUEHEX;

  // CONCATENATE TO FORM HEX COLOR CODE
  RETURN '#' + REDHEX + GREENHEX + BLUEHEX;
}

